481		if ok {
482			// 保持既有 JSON 形状：直接输出登记提案记录。
483			if cf.asJSON {
484				emitJSON(record)
485				return
486			}
487			printProposalText(record)
488			return
489		}
490		voteView, vok, verr := store.VoteProposal(*id)
491		if verr != nil {
492			fail(verr)
493		}
494		if !vok {
495			fail(fmt.Errorf("%w: %s", govflow.ErrProposalNotFound, *id))
496		}
497		if cf.asJSON {
498			emitJSON(voteView)
499			return
500		}
501		printVoteProposalText(voteView)
502	}
503	
504	func runProposals(args []string) {
505		cf := newCmdFlags("proposals")
506		cf.parse(args)
507		store, err := govflow.Open(cf.state)
508		if err != nil {
509			fail(err)
510		}
511		defer store.Close()
512		registered, err := store.Proposals()
513		if err != nil {
514			fail(err)
515		}
516		voting, err := store.VoteProposals()
517		if err != nil {
518			fail(err)
519		}
520		if cf.asJSON {
521			// 保持既有 JSON 形状：一个数组；登记记录字段不变，投票提案带额外字段。
522			merged := make([]any, 0, len(registered)+len(voting))
523			for _, r := range registered {
524				merged = append(merged, r)
525			}
526			for _, v := range voting {
527				merged = append(merged, v)
528			}
529			emitJSON(merged)
530			return
531		}
532		for _, record := range registered {
533			printProposalText(record)
534		}
535		for _, view := range voting {
536			printVoteProposalText(view)
537		}
538	}
539	
540	func runReceipt(args []string) {
541		cf := newCmdFlags("receipt")
542		id := cf.fs.String("id", "", "proposal id")
543		cf.parse(args)
544		if *id == "" {
545			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
546			os.Exit(2)
547		}
548		store, err := govflow.Open(cf.state)
549		if err != nil {
550			fail(err)
551		}
552		defer store.Close()
553		receipt, ok, err := store.Receipt(*id)
554		if err != nil {
555			fail(err)
556		}
557		if !ok {
558			fail(fmt.Errorf("no execution receipt for proposal %s", *id))
559		}
560		if cf.asJSON {
561			emitJSON(receipt)
562			return
563		}
564		printReceiptText(receipt, true)
565	}
566	
567	func runReceipts(args []string) {
568		cf := newCmdFlags("receipts")
569		cf.parse(args)
570		store, err := govflow.Open(cf.state)
571		if err != nil {
572			fail(err)
573		}
574		defer store.Close()
575		receipts, err := store.Receipts()
576		if err != nil {
577			fail(err)
578		}
579		if cf.asJSON {
580			emitJSON(receipts)
581			return
582		}
583		for _, receipt := range receipts {
584			printReceiptText(receipt, true)
585		}
586	}
587	
588	func printProposalText(p govflow.ProposalRecord) {
589		fmt.Printf("proposal %s state=%s timelock_end=%d actions=%d\n", p.ID, p.State, p.TimelockEnd, len(p.Actions))
590		for i, action := range p.Actions {
591			fmt.Printf("  action %d: %s\n", i, action)
592		}
593	}
594	
595	func printVoteProposalText(v *govflow.VoteProposalView) {
596		fmt.Printf("proposal %s source=vote state=%s quorum=%d voting=[%d,%d) timelock_end=%d actions=%d total_weight=%d\n",
597			v.ID, v.State, v.Quorum, v.StartAt, v.Deadline, v.TimelockEnd, len(v.Actions), v.TotalWeight)
598		for _, m := range v.Members {
599			chain := strings.Join(m.Path, "->")
600			if len(m.Path) == 1 {
601				fmt.Printf("  member %s weight=%d representative=self\n", m.ID, m.Weight)
602			} else {
603				fmt.Printf("  member %s weight=%d path=%s\n", m.ID, m.Weight, chain)
604			}
605		}
606		for i, action := range v.Actions {
607			fmt.Printf("  action %d: %s\n", i, action)
608		}
609		for _, b := range v.Ballots {
610			fmt.Printf("  ballot representative=%s choice=%s weight=%d voted_at=%d\n",
611				b.Representative, choiceWord(b.Support), b.Weight, b.VotedAt)
612		}
613		if v.Tally != nil {
614			verdict := "rejected"
615			if v.Tally.Passed {
616				verdict = "passed"
617			}
618			fmt.Printf("  tally for=%d against=%d turnout=%d => %s tallied_at=%d\n",
619				v.Tally.ForWeight, v.Tally.AgainstWeight, v.Tally.Turnout, verdict, v.Tally.TalliedAt)
620		}
621	}
622	
623	func printReceiptText(r *govflow.Receipt, header bool) {
624		if header {
625			fmt.Printf("receipt proposal=%s order=%d executed_at=%d actions=%d\n", r.ProposalID, r.Order, r.ExecutedAt, len(r.Actions))
626		} else {
627			fmt.Printf("executed proposal %s at %d (%d action(s)); receipt order %d\n", r.ProposalID, r.ExecutedAt, len(r.Actions), r.Order)
628		}
629		for _, ar := range r.Actions {
630			fmt.Printf("  action %d: %s\n", ar.Index, ar.Action)
631			fmt.Printf("    treasury:  %d -> %d\n", ar.Treasury.Before, ar.Treasury.After)
632			fmt.Printf("    %s: %d -> %d\n", ar.Recipient.Account, ar.Recipient.Before, ar.Recipient.After)
633		}
634	}
635	
636	func runDemo() {
637		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
638			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
639		if err := govflow.Vote(&proposal, 700, true); err != nil {
640			fmt.Println("vote refused:", err)
641		}
642		if err := govflow.Vote(&proposal, 200, false); err != nil {
643			fmt.Println("vote refused:", err)
644		}
645		next := govflow.Tally(&proposal)
646		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
647		proposal.State = next
648		proposal.TimelockEnd = 400
649		fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
650	}
